import{c as n,Z as e,Q as i,j as s,m as h,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"春晓","description":"","frontmatter":{"title":"春晓","author":"孟浩然","dynasty":"唐"},"headers":[],"relativePath":"books/shici/tangshi/2.md","filePath":"books/shici/tangshi/2.md"}'),l={name:"books/shici/tangshi/2.md"};function c(d,a,m,_,p,u){const o=e("PoemAuthor"),r=e("PoemNav");return i(),s("div",null,[a[0]||(a[0]=h('<h1 id="春晓" tabindex="-1">春晓 <a class="header-anchor" href="#春晓" aria-label="Permalink to &quot;春晓&quot;">​</a></h1><p><strong>[唐] <a href="/authors/menghaoran.html">孟浩然</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>春眠不觉晓，处处闻啼鸟。 夜来风雨声，花落知多少。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>晓：天亮</li><li>闻：听见</li><li>啼鸟：鸟啼，鸟的叫声</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>春天的夜晚睡得很香甜，不知不觉天就亮了。醒来时到处都能听到鸟儿欢快的鸣叫声。回想起昨夜的风雨声，不知道有多少花朵被打落了。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是诗人隐居在鹿门山时所作，意境十分优美。诗人抓住春晨生活的一刹那，描写了春睡香甜、鸟鸣悦耳、风雨过后落花满地的情景，表达了对春天的热爱和对春光流逝的淡淡惋惜。全诗语言清新自然，韵味无穷，是脍炙人口的咏春名篇。</p>',10)),t(o,{name:"孟浩然",years:"689年－740年",desc:"唐代著名山水田园诗人，与王维并称“王孟”。其诗清淡自然，多写山水田园和隐逸生活。",link:"/authors/menghaoran"}),t(r)])}const P=n(l,[["render",c]]);export{b as __pageData,P as default};
